'use strict';
const form=document.querySelector('#bundle'),status=document.querySelector('#status'),enc=new TextEncoder(),dec=new TextDecoder(),key='task-author-stage3-v1';
let files=new Map(),loadIssues=[],revision=0;
function read(k){try{return JSON.parse(localStorage.getItem(k)||'null');}catch{return null;}}
function drafts(){return {idea:read('task-author-stage1-v1')?.data||{},spec:read('task-author-stage2-v1')?.data||{}};}
function collect(){const d={};for(const e of form.elements)if(e.name)d[e.name]=e.type==='checkbox'?e.checked:e.value;return d;}
function save(){try{localStorage.setItem(key,JSON.stringify({schema:'task-author.bundle.v1',data:collect()}));status.textContent='Metadata saved locally. Reselect files after a reload.';}catch{status.textContent='Storage unavailable; export a metadata backup.';}}
function invalidate(){revision++;document.querySelector('#zip').disabled=true;document.querySelector('#report').hidden=true;}
function quote(s){return JSON.stringify(String(s??'')).replace(/[\u0000-\u0007\u000b\u000e-\u001f]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'));}
function toml(){const {idea:i,spec:s}=drafts(),d=collect(),tags=d.tags.split(',').map(x=>x.trim()).filter(Boolean),artifacts=(s.artifacts||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),line=(k,v)=>k+' = '+quote(v),num=x=>Number.isFinite(Number(x))?Number(x):0;let text=['schema_version = "1.4"','artifacts = '+JSON.stringify(artifacts),'','[task]',line('name','afterquery/'+(s.slug||'')),line('description',s.description),'authors = [{ name = '+quote(d.authorName)+', email = '+quote(d.email)+' }]','keywords = '+JSON.stringify(tags),'','[metadata]',line('author_name',d.authorName),line('author_email',d.email),line('author_organization',i.affiliation),line('author_profile',i.profile),line('research_advisor',d.advisor),line('referred_by',d.referral),line('conflicts_of_interest',i.conflicts),line('domain',i.domain),line('field',i.field),line('subfield',i.subfield),'category = "Science"',line('subcategory',fieldName(i.field)),'tags = '+JSON.stringify(tags),'expert_time_estimate_hours = '+num(i.expertHours),line('relevant_experience',i.experience),line('difficulty_explanation',`${i.difficulty||''}\nData type: ${i.dataType||''}\n${i.provenance||''}`),line('solution_explanation',d.solution),line('verification_explanation',`${s.truth||''}\n${s.acceptance||''}\n${s.baselines||''}\n${s.tolerances||''}\n${s.determinism||''}`),'','[verifier]','timeout_sec = '+num(s.verifierSeconds),'environment_mode = "separate"','','[verifier.environment]','network_mode = "no-network"','','[agent]','timeout_sec = '+num(s.agentSeconds),'','[environment]','build_timeout_sec = 600.0','cpus = '+num(s.cpus),'memory_mb = '+num(s.memory),'storage_mb = '+num(s.storage),'gpus = '+num(s.gpu)];if(s.gpu==='1')text.push('gpu_types = ["H100"]');text.push('network_mode = "public"');return text.join('\n')+'\n';}
function fieldName(slug){return {'biology':'Biology & Biotechnology','ecology':'Ecology & Evolutionary Biology','medicine':'Medicine & Health Sciences','neuroscience':'Neuroscience & Cognitive Science','astronomy':'Astronomy & Astrophysics','chemistry':'Chemistry','materials-science':'Materials Science & Engineering','physics':'Physics','atmospheric-sciences':'Atmospheric & Climate Sciences','environmental-sciences':'Environmental & Sustainability Sciences','geosciences':'Geosciences & Planetary Science','ocean-sciences':'Ocean & Marine Sciences','applied-mathematics':'Applied Mathematics & Scientific Computing','formal-mathematics':'Formal Mathematics & Theorem Proving','operations-research':'Operations Research & Optimization','statistics':'Statistics & Machine Learning','chemical-engineering':'Chemical & Biomolecular Engineering','civil-engineering':'Civil & Structural Engineering','electrical-engineering':'Electrical & Computer Engineering','mechanical-engineering':'Mechanical & Aerospace Engineering'}[slug]||'';}
function context(){const {idea,spec}=drafts();document.querySelector('#context').textContent=`Idea: ${idea.title||'missing'} · Task: ${spec.slug?'afterquery/'+spec.slug:'missing'} · Field: ${fieldName(idea.field)||'missing'}. Earlier stages are self-reported, not approved.`;}
function assembled(){const m=new Map(files);const s=drafts().spec;m.set('instruction.md',enc.encode(s.instruction||''));m.set('task.toml',enc.encode(toml()));m.set('README.md',enc.encode(form.elements.readme.value));return m;}
function issues(){const {idea:i,spec:s}=drafts(),d=collect(),out=[...loadIssues];for(const e of form.elements)if(e.required&&(!e.value.trim()||!e.checkValidity()))out.push('Complete or correct: '+e.closest('label').childNodes[0].textContent.trim());for(const k of ['reviewed','sealed','dependencies','reward','conflict'])if(!d[k])out.push('Declaration missing: '+form.elements[k].parentElement.textContent.trim());
for(const k of ['title','domain','field','subfield','affiliation','profile','conflicts','experience','difficulty','provenance','dataType','truthEvidence','originality','problem','deliverables','failure','verification'])if(!i[k]?.trim())out.push('Stage 1 incomplete: '+k);if(!(Number.isFinite(Number(i.expertHours))&&Number(i.expertHours)>0))out.push('Stage 1 expert hours must be positive.');const groups={'life-sciences':['biology','ecology','medicine','neuroscience'],'physical-sciences':['astronomy','chemistry','materials-science','physics'],'earth-sciences':['atmospheric-sciences','environmental-sciences','geosciences','ocean-sciences'],'mathematical-sciences':['applied-mathematics','formal-mathematics','operations-research','statistics'],'engineering-sciences':['chemical-engineering','civil-engineering','electrical-engineering','mechanical-engineering']};if(!groups[i.domain]?.includes(i.field))out.push('Domain and field must match the approved taxonomy.');for(const k of ['authorship','realWork','novel','fair','internet','isolation','independent'])if(!i[k])out.push('Stage 1 declaration missing: '+k);if(i.truthSource!=='independent'||i.knownConflict!=='no')out.push('Stage 1 ground truth or conflict status requires resolution.');
for(const k of ['description','acceptance','truth','baselines','tolerances','determinism','timing','environment','instruction'])if(!s[k]?.trim())out.push('Stage 2 incomplete: '+k);if(!/^[a-z0-9]+(-[a-z0-9]+){0,2}$/.test(s.slug||''))out.push('Invalid task slug.');for(const k of ['isolation','offline','services','authorOwned','manual'])if(!s[k])out.push('Stage 2 declaration missing: '+k);if(s.exceptions?.trim())out.push('Stage 2 proposed exception requires discussion and user permission.');if(!Number.isInteger(+s.agentSeconds)||+s.agentSeconds<9000||+s.agentSeconds>28800)out.push('Agent timeout must be an integer from 9000 to 28800.');if(s.verifierSeconds===''||!Number.isFinite(+s.verifierSeconds)||+s.verifierSeconds<0||+s.verifierSeconds>13500)out.push('Verifier timeout must be between 0 and 13500.');if(![1,2,4,8,16].includes(+s.cpus)||![1024,2048,4096,8192,16384].includes(+s.memory)||!(Number.isInteger(+s.storage)&&+s.storage>0&&+s.storage<=40960)||!['0','1'].includes(s.gpu))out.push('Resources are missing or outside the permitted settings.');
if(!d.tags.split(',').some(x=>x.trim()))out.push('At least one nonempty tag is required.');if(!['yes','no'].includes(s.numeric))out.push('Stage 2 numerical grading choice is missing.');const paths=(s.artifacts||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!paths.length||new Set(paths).size!==paths.length||paths.some(p=>!/^\/(?!\/)[^\s\\]+$/.test(p)||p.endsWith('/')||p.split('/').some(x=>x==='.'||x==='..')))out.push('Artifact paths must be unique absolute Linux file paths.');for(const p of paths)if(!s.instruction?.includes(p))out.push('Instruction does not mention artifact: '+p);const instruction=s.instruction||'',ending=`\n\nYou have ${s.agentSeconds} seconds to complete this task. Do not cheat by using online solutions or hints specific to this task.`;if(!(instruction.endsWith(ending)||instruction.endsWith(ending+'\n')))out.push('Instruction does not have the exact source-required ending.');if(/^\s{0,3}#{1,6}\s/m.test(instruction)||/^\s*(?:\d+[.)]|[-*+])\s/m.test(instruction))out.push('Instruction must be plain prose without Markdown headings or step lists.');for(const section of ['Difficulty','Reference solution','Verification'])if(!d.readme.split(/\r?\n/).some(x=>x.trim()==='## '+section))out.push('README missing section: '+section);
const m=assembled();out.push(...BundleCore.scan(m));for(const p of ['instruction.md','task.toml','README.md'])if(files.has(p)&&dec.decode(files.get(p))!==dec.decode(m.get(p)))out.push('Folder file differs from saved/editor content: '+p+'. Reconcile it explicitly before exporting.');for(const [p,b] of m){if(/\.(?:png|jpg|jpeg|pdf|zip|gz|npy|npz|parquet|bin)$/i.test(p))continue;const t=dec.decode(b);if(/harbor-canary.*[0-9a-f]{8}-[0-9a-f-]{27,}/i.test(t))out.push('Prohibited eval-set canary marker: '+p);if(p.endsWith('Dockerfile')&&/FROM\s+--platform=/i.test(t))out.push('Prohibited FROM --platform pin: '+p);if(p==='environment/Dockerfile'){const user=[...t.matchAll(/^\s*USER\s+(\S+)/gmi)].pop();if(user&&user[1]!=='root'&&user[1]!=='0')out.push('Environment Dockerfile must end as root; configure agent user in task.toml.');}if(p==='tests/test.sh'&&/\b(?:pip|uv)\s+(?:pip\s+)?install\b/.test(t))out.push('Verifier must not install tools at runtime.');}
const verifier=dec.decode(m.get('tests/Dockerfile')||new Uint8Array());for(const pin of ['pytest==8.4.1','pytest-json-ctrf==0.3.5'])if(!verifier.includes(pin))out.push('Verifier Dockerfile missing required pin: '+pin);if(!/COPY\s+\.\s+\/tests\//i.test(verifier))out.push('Verifier Dockerfile must bake tests with COPY . /tests/.');return [...new Set(out)];}
function review(){const errors=issues(),el=document.querySelector('#report');el.replaceChildren();const h=document.createElement('h2');h.textContent=errors.length?'Bundle needs attention':'Preparation checks passed · Harbor validation pending';el.append(h);const ul=document.createElement('ul');for(const text of errors){const li=document.createElement('li');li.textContent=text;ul.append(li);}el.append(ul);const p=document.createElement('p');p.textContent='Remaining: actual oracle/nop runs, determinism, test coverage, dependency pinning in all manifests, leakage inspection, numerical robustness, anti-cheat, and external review. The difficulty threshold contradiction is unresolved. No source rule is waived by export.';el.append(p);el.hidden=false;document.querySelector('#zip').disabled=errors.length>0;document.querySelector('#toml').textContent=toml();return errors;}
form.addEventListener('input',()=>{invalidate();save();});form.addEventListener('change',e=>{if(e.target.id!=='folder'&&e.target.id!=='backupFile'){invalidate();save();}});document.querySelector('#check').onclick=()=>{save();review();document.querySelector('#report').scrollIntoView({behavior:'smooth'});};
document.querySelector('#folder').onchange=async e=>{invalidate();const current=revision,selected=[...e.target.files];document.querySelector('#zip').disabled=true;files=new Map();loadIssues=[];if(selected.reduce((n,f)=>n+f.size,0)>100*1024*1024){loadIssues.push('Folder exceeds this app’s 100 MB limit.');}else{const loaded=new Map();for(const f of selected){const p=f.webkitRelativePath.split('/').slice(1).join('/');const issue=BundleCore.pathIssue(p);if(issue)loadIssues.push(issue);if(loaded.has(p))loadIssues.push('Duplicate file path: '+p);loaded.set(p,new Uint8Array(await f.arrayBuffer()));}if(current!==revision)return;files=loaded;}document.querySelector('#inventory').textContent=files.size?[...files].map(([p,b])=>`${p} · ${b.length.toLocaleString()} bytes`).join('\n'):'No files loaded.';status.textContent='Folder read locally. Run Check bundle again.';};
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
document.querySelector('#zip').onclick=()=>{try{if(review().length)return;download(new Blob(BundleCore.zip(assembled()),{type:'application/zip'}),(drafts().spec.slug||'task')+'-preparation.zip');status.textContent='Preparation ZIP exported. Harbor and external review have not run.';}catch(e){status.textContent='Export failed: '+e.message;}};
document.querySelector('#backup').onclick=()=>{save();download(new Blob([JSON.stringify({schema:'task-author.bundle.v1',data:collect()},null,2)],{type:'application/json'}),'bundle-metadata.json');};document.querySelector('#restore').onclick=()=>document.querySelector('#backupFile').click();
function hydrate(d){if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid metadata');form.reset();for(const e of form.elements)if(e.name&&Object.hasOwn(d,e.name)){if(e.type==='checkbox')e.checked=d[e.name]===true;else if(typeof d[e.name]==='string')e.value=d[e.name];}}
document.querySelector('#backupFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Backup exceeds 2 MB');const p=JSON.parse(await f.text());if(p.schema!=='task-author.bundle.v1')throw Error('Unrecognized metadata backup');hydrate(p.data);files=new Map();loadIssues=[];document.querySelector('#inventory').textContent='No folder selected. Reselect files after importing metadata.';invalidate();save();}catch(err){status.textContent='Import failed: '+err.message;}e.target.value='';};
window.addEventListener('focus',()=>{context();invalidate();});const stored=read(key);if(stored?.schema==='task-author.bundle.v1')try{hydrate(stored.data);}catch{}context();
